const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const N = data[0];
const M = data[1];
const conflicts = new Int32Array(N);

let pos = 2;
for (let i = 0; i < M; i++) {
  const x = data[pos++] - 1;
  const y = data[pos++] - 1;
  conflicts[x] |= 1 << y;
  conflicts[y] |= 1 << x;
}

const limit = 1 << N;
const valid = new Uint8Array(limit);
valid[0] = 1;

let count = 0;
for (let mask = 1; mask < limit; mask++) {
  const bit = mask & -mask;
  const vertex = 31 - Math.clz32(bit);
  const rest = mask ^ bit;

  if (valid[rest] && (conflicts[vertex] & rest) === 0) {
    valid[mask] = 1;
    count++;
  }
}

console.log(count.toString());
